@startuml

enum Suit {
  DIAMONDS
  HEARTS
  SPADES
  CLUBS
}

enum ComparisonResult {
  LOWER
  EQUAL
  HIGHER
}

enum SoloType {
  TRUMP
  JACK
  QUEEN
}

abstract class CardGameObject {
  + id : string
}

class Game extends CardGameObject {
}

class Player extends CardGameObject {
}

class Deck extends CardGameObject {
}

class Card extends CardGameObject {
  + suit : Suit
  + compareHeight(other : Card) : ComparisonResult
}

class ScoringTable extends CardGameObject {
}

class Round extends CardGameObject {
  + pointValue : int
}

class JackRound extends Round {}

class SoloRound extends Round {
  + soloType : SoloType
}

class MandatorySoloRound extends SoloRound {}

class WinningPlayer {
}

